using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var tools = new ResearchTools();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When the user gives you a topic:
        1. Search the web for relevant information using the search tool (2-3 queries).
        2. Save each key finding as a note using the note-taking tool.
        3. After gathering enough information, write a concise summary that synthesizes your notes.
        Always cite your sources. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.SaveNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ]);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (MAF + MEAI)    ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        break;
    }

    Console.WriteLine($"\nResearching: {topic}...\n");

    tools.ClearNotes();

    try
    {
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
        });

        AgentResponse response = await agent.RunAsync(
            $"Research the following topic and provide a summary: {topic}",
            options: runOptions);

        Console.WriteLine("───── Research Summary ─────");
        Console.WriteLine(response.Text);
        Console.WriteLine("────────────────────────────");

        if (tools.NoteCount > 0)
        {
            Console.WriteLine($"\n📝 {tools.NoteCount} note(s) saved during research.");
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
    }
}

Console.WriteLine("Goodbye!");

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
sealed class ResearchTools
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
    };

    private readonly List<Note> _notes = [];

    public int NoteCount => _notes.Count;

    public void ClearNotes() => _notes.Clear();

    [Description("Search the web for information on a given query. Returns a list of search results with titles, URLs, and snippets.")]
    public async Task<IReadOnlyList<SearchResult>> SearchWeb(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        try
        {
            // Use the DuckDuckGo Instant Answer API (no key required)
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await s_httpClient.GetFromJsonAsync<JsonElement>(url);
            var results = new List<SearchResult>();

            // Extract the abstract (main result)
            var abstractText = response.GetProperty("Abstract").GetString();
            var abstractUrl = response.GetProperty("AbstractURL").GetString();
            var abstractSource = response.GetProperty("AbstractSource").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                results.Add(new SearchResult(abstractSource ?? "Web", abstractUrl ?? "", abstractText));
            }

            // Extract related topics
            if (response.TryGetProperty("RelatedTopics", out var relatedTopics))
            {
                foreach (var topic in relatedTopics.EnumerateArray())
                {
                    if (results.Count >= maxResults)
                    {
                        break;
                    }

                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;

                    if (!string.IsNullOrEmpty(text))
                    {
                        results.Add(new SearchResult("DuckDuckGo", firstUrl ?? "", text));
                    }
                }
            }

            if (results.Count == 0)
            {
                results.Add(new SearchResult("Info", "", $"No direct results found for '{query}'. Try a more specific query."));
            }

            return results;
        }
        catch (Exception ex)
        {
            return [new SearchResult("Error", "", $"Search failed: {ex.Message}")];
        }
    }

    [Description("Save a research note with a title and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The content of the note")] string content,
        [Description("The source URL, if applicable")] string? sourceUrl = null)
    {
        _notes.Add(new Note(title, content, sourceUrl));
        return $"Note saved: '{title}' (total notes: {_notes.Count})";
    }

    [Description("Retrieve all saved research notes. Use this to review findings before writing a summary.")]
    public IReadOnlyList<Note> GetNotes()
    {
        return _notes.AsReadOnly();
    }
}

record SearchResult(string Title, string Url, string Snippet);

